    resolveArtistSongForDetail(song, artist).then(function (found) {
      openTrackDetailModal('artist', found || Object.assign({}, song, { artist: artist }));
    }).catch(function () {
      openTrackDetailModal('artist', Object.assign({}, song, { artist: artist }));
    });
