  if (info.configured || info.searchReady) return "Spotify 搜尋已可用；登錄後可同步會員狀態、歌單和紅心歌單";
  var missing = info.oauthMissing && info.oauthMissing.length ? (' 缺少: ' + info.oauthMissing.join(', ')) : '';
