async function checkQr() {
  if (!qrKey) return;
  try {
    var r = await apiJson('/api/login/qr/check?key=' + encodeURIComponent(qrKey));
    var $st = document.getElementById('qr-status');
    if (r.code === 800) { $st.textContent = "二維碼已過期, 請刷新"; $st.className = 'fail'; stopQrPoll(); }
    else if (r.code === 801) { $st.textContent = "請在 App 中掃碼"; $st.className = ''; }
    else if (r.code === 802) { $st.textContent = "已掃碼, 請在手機確認…"; $st.className = 'scan'; }
    else if (r.code === 803 && (r.loggedIn || r.hasCookie)) {
      $st.textContent = r.pendingProfile ? "登錄成功，正在同步賬號資料…" : "登錄成功！"; $st.className = 'scan';
      stopQrPoll();
      loginStatus = r.loggedIn ? r : Object.assign({}, r, { loggedIn: true, pendingProfile: true, nickname: r.nickname || "網易雲用戶" });
      activeAccountProvider = 'netease';
      renderUserBtn();
      setTimeout(async function () {
        var fresh = await refreshLoginStatus(true);
        if (!fresh || !fresh.loggedIn) {
          loginStatus = Object.assign({}, loginStatus, { loggedIn: true, pendingProfile: true });
          renderUserBtn();
          fresh = loginStatus;
        }
        closeLoginModal();
        offerLoginCookieExport('netease', fresh);
        showToast("歡迎 " + (fresh && fresh.nickname ? fresh.nickname : ''));
      }, r.pendingProfile ? 1200 : 500);
    } else if (r.code === 803) {
      $st.textContent = "掃碼已確認，但沒有拿到登錄憑證，請刷新二維碼重試"; $st.className = 'fail';
      stopQrPoll();
    }
  } catch (e) { console.warn(e); }
}


